scwin.grdMyMenuInfo_onbeforeedit = function(row, col, value) {
    // 폴더인지 확인
    var rowData = PsnFuncMyMenuVO.getDataRow(row);
    // 폴더일 경우 변경 명 수정
    if (rowData.printSeq == 1 && rowData.menuId.length == 0) {
        return true;
    }
    return false;
};
scwin.displayFomatter = function(value) {
    var rowData = PsnFuncMyMenuVO.getMatchedJSON("menuNm", value);
    if (rowData.length == 0) {
        return value;
    }
    var delVal = "";
    // if (!com.util.isEmpty( rowData[0].menuId )) {	// 메뉴
    if (rowData[0].menuId != "") { // 메뉴
        if (rowData[0].useYn == 'N') {
            delVal = "<a class=\"btn btn_del\"></a>";
        }
        value = value.split('^')[0];
        value = delVal + value + "<w2:anchor class=\"btn_leftarea path\" outerDiv=\"false\" title=\"" + rowData[0].pathNm + "\">\"";
    } else { // 폴더
        value = delVal + "<strong>" + value + "</strong>";
    }
    return value;
};
