scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_grdMyMenuInfo__menuNm', 'key-sequence', {
        sequence: '가나다'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_grdMyMenuInfo__menuNm', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdMyMenuInfo_cell_7_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'grdMyMenuInfo__menuNm').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /***************************************************************************************
     * 업무명 		: 개인화기능_나의메뉴
     * 파일명 		: ZZZB080P01
     * 작성자 		: esj93494
     * 작성일 		: 2020.11.27
     *
     * 설  명		: 자주사용하는 메뉴를 관리할 수 있다.
     *---------------------------------------------------------------------------------------
     * 변경일		변경자		변경내역 
     *---------------------------------------------------------------------------------------
     * 2020.11.27	esj93494	최초 프로그램 작성         
     * 
     *---------------------------------------------------------------------------------------
     ****************************************************************************************/
    /***************************************************************************************
     * 01. Form 변수정의									
     ***************************************************************************************/
    /***************************************************************************************
     * 02. Form 화면초기화									
     ***************************************************************************************/
    /*
     *	@라벨명
     *	
     *	@이벤트명
     *	grdMyMenuInfo_onbeforeedit
     *	@이벤트유형
     *	onbeforeedit
     *	@이벤트설명
     *	그리드 에디트 모드 접근 전 폴더일 경우만 허용
     *	@입력데이터
     *	
     *	@출력데이터
     *	
     *	@호출화면/서비스
     *	
     */
    /*
     *	@이벤트명
     *	displayFomatter
     *	@이벤트설명
     *	그리드 컬럼 place holder 적용
     */
    /*
     *	@라벨명
     *	
     *	@이벤트명
     *	grdMyMenuInfo_onafteredit
     *	@이벤트유형
     *	onafteredit
     *	@이벤트설명
     *	그리드 에디트 모드 접근 후 폴더명 변경 시 하위 메뉴도 함께 폴더명 변경
     *	@입력데이터
     *	
     *	@출력데이터
     *	
     *	@호출화면/서비스
     *	
     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
